/*
 * This is the primary high-level API for the project. In this folder there should be:
 * A class called InsightFacade, this should be in a file called InsightFacade.ts.
 * You should not change this interface at all or the test suite will not work.
 */

export enum InsightDatasetKind {
	Sections = "sections",
	Rooms = "rooms",
}

export interface InsightDataset {
	id: string;
	kind: InsightDatasetKind;
	numRows: number;
}

export type InsightResult = Record<string, string | number>;

export class InsightError extends Error {
	constructor(message?: string) {
		super(message);
		Error.captureStackTrace(this, InsightError);
	}
}

export class NotFoundError extends Error {
	constructor(message?: string) {
		super(message);
		Error.captureStackTrace(this, NotFoundError);
	}
}

export class ResultTooLargeError extends Error {
	constructor(message?: string) {
		super(message);
		Error.captureStackTrace(this, ResultTooLargeError);
	}
}

export interface IInsightFacade {
	/**
	 * Add a dataset to insightUBC.
	 *
	 * @param id  The id of the dataset being added. Follows the format /^[^_]+$/
	 * @param content  The base64 content of the dataset. This content should be in the form of a serialized zip file.
	 * @param kind  The kind of the dataset
	 *
	 * @return Promise <string[]>
	 *
	 * The promise should fulfill on a successful add, reject for any failures.
	 * The promise should fulfill with a string array,
	 * containing the ids of all currently added datasets upon a successful add.
	 * The promise should reject with an InsightError describing the error.
	 *
	 * An id is invalid if it contains an underscore, or is only whitespace characters.
	 * If id is the same as the id of an already added dataset, the dataset should be rejected and not saved.
	 *
	 * After receiving the dataset, it should be processed into a data structure of
	 * your design. The processed data structure should be persisted to disk; your
	 * system should be able to load this persisted value into memory for answering
	 * queries.
	 *
	 * Ultimately, a dataset must be added or loaded from disk before queries can
	 * be successfully answered.
	 */
	addDataset(id: string, content: string, kind: InsightDatasetKind): Promise<string[]>;

	/**
	 * Remove a dataset from insightUBC.
	 *
	 * @param id  The id of the dataset to remove. Follows the format /^[^_]+$/
	 *
	 * @return Promise <string>
	 *
	 * The promise should fulfill upon a successful removal, reject on any error.
	 * Attempting to remove a dataset that hasn't been added yet counts as an error.
	 *
	 * An id is invalid if it contains an underscore, or is only whitespace characters.
	 *
	 * The promise should fulfill the id of the dataset that was removed.
	 * The promise should reject with a NotFoundError (if a valid id was not yet added)
	 * or an InsightError (invalid id or any other source of failure) describing the error.
	 *
	 * This will delete both disk and memory caches for the dataset for the id meaning
	 * that subsequent queries for that id should fail unless a new addDataset happens first.
	 */
	removeDataset(id: string): Promise<string>;

	/**
	 * Perform a query on insightUBC.
	 *
	 * @param query  The query to be performed.
	 *
	 * If a query is incorrectly formatted, references a dataset not added (in memory or on disk),
	 * or references multiple datasets, it should be rejected.
	 *
	 * @return Promise <InsightResult[]>
	 *
	 * The promise should fulfill with an array of results.
	 * The promise should reject with a ResultTooLargeError (if the query returns too many results)
	 * or an InsightError (for any other source of failure) describing the error.
	 */
	performQuery(query: unknown): Promise<InsightResult[]>;

	/**
	 * List all currently added datasets, their types, and number of rows.
	 *
	 * @return Promise <InsightDataset[]>
	 * The promise should fulfill an array of currently added InsightDatasets, and will only fulfill.
	 */
	listDatasets(): Promise<InsightDataset[]>;
}

import DatasetProcessor from "./DatasetProcessor";
import {
	IInsightFacade,
	InsightDataset,
	InsightDatasetKind,
	InsightError,
	NotFoundError,
	InsightResult,
} from "./IInsightFacade";
import QueryValidator from "./QueryValidator";
import QueryEngine from "./QueryEngine";
// import Log from "../../util/Log";

/**
 * This is the main programmatic entry point for the project.
 * Method documentation is in IInsightFacade
 *
 */
export default class InsightFacade implements IInsightFacade {
	public datasetMap: Map<string, InsightDataset> = new Map<string, InsightDataset>();

	public async addDataset(id: string, content: string, kind: InsightDatasetKind): Promise<string[]> {
		const fs = require("fs-extra");
		const filePath = "./data/" + id + ".json";
		const dsProcessor = new DatasetProcessor();

		try {
			// Check if the ID is valid
			if (this.invalidId(id)) {
				throw new InsightError("Invalid ID");
			}

			// Check if dataset already exists in memory
			if (this.datasetMap.has(id)) {
				throw new InsightError("Duplicated Id (already in memory)");
			}

			// Check if dataset already exists on disk
			const existsOnDisk = await fs.pathExists(filePath);
			if (existsOnDisk) {
				throw new InsightError("Duplicated Id (already on disk)");
			}

			// Process the dataset
			const ds = await dsProcessor.addSectionsDataset(id, content, kind);
			this.datasetMap.set(ds.id, ds);

			// Get all dataset IDs (from both memory and disk)
			const allDatasetIds = await this.getAllDatasetIds();
			return allDatasetIds;
		} catch (err) {
			throw new InsightError(`Error adding dataset: ${err} `);
		}
	}

	public async removeDataset(id: string): Promise<string> {
		const fs = require("fs-extra");
		const filePath = "./data/" + id + ".json";

		return new Promise<string>((resolve, reject) => {
			if (this.invalidId(id)) {
				return reject(new InsightError("Invalid ID"));
			}

			// Check if the dataset exists in memory
			if (!this.datasetMap.has(id)) {
				// If not found in memory, check if the dataset exists on disk
				fs.pathExists(filePath)
					.then((existsOnDisk: any) => {
						if (!existsOnDisk) {
							return reject(new NotFoundError(`Dataset with id '${id}' not found in memory or disk.`));
						}

						// Delete dataset from disk
						return fs.remove(filePath);
					})
					.then(() => {
						return resolve(id);
					})
					.catch(() => {
						return reject(new InsightError("Error removing dataset"));
					});
			} else {
				// If found in memory, remove from memory and disk
				this.datasetMap.delete(id);
				fs.remove(filePath)
					.then(() => {
						return resolve(id);
					})
					.catch(() => {
						return reject(new InsightError("Error removing dataset from disk"));
					});
			}
		});
	}

	public async performQuery(query: unknown): Promise<InsightResult[]> {
		try {
			const queryValidator = new QueryValidator("");

			// Validate the query
			if (!queryValidator.isValidQuery(query)) {
				throw new InsightError("Invalid Query");
			}

			const id = queryValidator.datasetID;

			// Check if the dataset exists in the map, otherwise load it from disk
			if (!this.datasetMap.has(id)) {
				const datasetsFromDisk = await this.readFromDisk();
				datasetsFromDisk.forEach((ds) => {
					if (ds.id === id) {
						this.datasetMap.set(ds.id, ds);
					}
				});

				// If the dataset was still not found after reading from disk, throw an error
				if (!this.datasetMap.has(id)) {
					throw new InsightError(`Dataset with ID ${id} not found.`);
				}
			}

			// Process the query using the query engine
			const queryEngine = new QueryEngine(id);
			const queryResult = queryEngine.processQuery(query, id, this.datasetMap);
			return queryResult;
		} catch (err) {
			return Promise.reject(err);
		}
	}

	public async listDatasets(): Promise<InsightDataset[]> {
		return new Promise<InsightDataset[]>((resolve, reject) => {
			this.readFromDisk()
				.then((datasetsFromDisk) => {
					datasetsFromDisk.forEach((ds) => {
						this.datasetMap.set(ds.id, ds);
					});

					return resolve(Array.from(this.datasetMap.values()));
				})
				.catch(() => {
					return reject("Error listing datasets from disk");
				});
		});
	}

	private invalidId(id: string): boolean {
		if (id === null) {
			return true;
		}
		if (id.trim() === "") {
			return true;
		}
		if (id.includes("_")) {
			return true;
		}

		return false;
	}

	private async readFromDisk(): Promise<InsightDataset[]> {
		await this.checkDirectoryExists("./data/");
		const files = await this.readDirectory("./data/");

		if (files.length === 0) {
			return [];
		}

		const datasets = await this.readJsonFiles(files);
		return datasets;
	}

	private async checkDirectoryExists(dirPath: string): Promise<void> {
		const fs = require("fs-extra");
		const exists = await fs.pathExists(dirPath);
		if (!exists) {
			throw new InsightError(`Directory does not exist.`);
		}
	}

	private async readDirectory(dirPath: string): Promise<string[]> {
		const fs = require("fs-extra");
		return await fs.readdir(dirPath);
	}

	private async readJsonFiles(files: string[]): Promise<InsightDataset[]> {
		const fs = require("fs-extra");
		const result: InsightDataset[] = [];

		const readJsonPromises = files.map(async (file) => {
			const jsonObj = await fs.readJson("./data/" + file);
			const dataset: InsightDataset = {
				id: file.replace(".json", ""),
				kind: InsightDatasetKind.Sections,
				numRows: jsonObj.length,
			};
			result.push(dataset);
		});

		await Promise.all(readJsonPromises);
		return result;
	}

	private async getAllDatasetIds(): Promise<string[]> {
		const fs = require("fs-extra");

		// Get datasets on disk
		const files = await fs.readdir("./data/");
		const allDatasetIds = files.map((file: any) => file.replace(".json", ""));

		return allDatasetIds;
	}
}

import JSZip from "jszip";
import { InsightDataset, InsightDatasetKind, InsightError } from "./IInsightFacade";
import Section from "../model/Section";
import SectionsDataset from "../model/SectionsDataset";
// import Log from "../../util/Log";

export default class DatasetProcessor {
	public async addSectionsDataset(id: string, content: string, kind: InsightDatasetKind): Promise<InsightDataset> {
		const jszip = new JSZip();

		return new Promise<InsightDataset>((resolve, reject) => {
			// Load zip content
			jszip
				.loadAsync(content, { base64: true })
				.then(async (zip) => this.pushAllSection(zip, reject))
				.then((allSections) => {
					// Wait until all courses are processed
					Promise.all(allSections)
						.then((coursesResult) => this.pushValidSection(coursesResult))
						.then(async (allValidSections) => {
							// check if the valid sections are empty AFTER all courses have been processed
							if (allValidSections.length === 0) {
								return reject(new InsightError("Not a single valid section found"));
							}

							// Return an InsightDataset with all the valid sections added AFTER all courses have been processed
							const allPrefixedSections = [];
							for (const section of allValidSections) {
								allPrefixedSections.push(section.getPrefixedFields(id) as Section);
							}
							const ds = new SectionsDataset(id, kind, allValidSections.length, allPrefixedSections);
							await this.storeToDisk(ds);
							return resolve(ds);
						})
						.catch((err) => {
							return reject(err);
						});
				})
				.catch((err) => {
					return reject(err);
				});
		});
	}

	private async storeToDisk(ds: SectionsDataset): Promise<void> {
		const fs = require("fs-extra");
		try {
			// Ensure the directory exists
			await fs.ensureDir("./data");

			// Write the dataset's sections to a JSON file
			await fs.writeJson("./data/" + ds.id + ".json", ds.sections);
		} catch (err) {
			throw new InsightError(`Error storing json file to disk: ${err}`);
		}
	}

	private async pushAllSection(zip: JSZip, reject: (error: InsightError) => void): Promise<Promise<string>[]> {
		const allSections: Promise<string>[] = [];
		const coursesFolder = zip.folder(/^courses\/$/);

		// Check if courses folder exists and is at root level
		if (coursesFolder !== null) {
			let numberOfFiles = 0;
			zip.folder("courses")?.forEach(function (_relativePath: string, file: any) {
				numberOfFiles++;
				allSections.push(file.async("string"));
			});

			if (numberOfFiles === 0) {
				reject(new InsightError("courses folder is empty"));
				return Promise.reject();
			}
		} else {
			reject(new InsightError("courses folder not found"));
			return Promise.reject();
		}

		return allSections;
	}

	private pushValidSection(listOfResult: string[]): Section[] {
		const allValidSections: Section[] = [];

		for (const JSONfile of listOfResult) {
			const course = JSON.parse(JSONfile);
			// make sure each result key exists
			if (!Object.prototype.hasOwnProperty.call(course, "result")) {
				continue;
			}
			for (const section of course.result) {
				// If a section has missing field, it is invalid (skip it)
				if (this.missingQueryKey(section)) {
					continue;
				}
				const validSection = new Section(section);
				allValidSections.push(validSection);
			}
		}

		return allValidSections;
	}

	private missingQueryKey(section: any): boolean {
		if (!Object.prototype.hasOwnProperty.call(section, "Course")) {
			return true;
		}
		if (!Object.prototype.hasOwnProperty.call(section, "Title")) {
			return true;
		}
		if (!Object.prototype.hasOwnProperty.call(section, "Professor")) {
			return true;
		}
		if (!Object.prototype.hasOwnProperty.call(section, "Subject")) {
			return true;
		}
		if (!Object.prototype.hasOwnProperty.call(section, "Year")) {
			return true;
		}
		if (!Object.prototype.hasOwnProperty.call(section, "Avg")) {
			return true;
		}
		if (!Object.prototype.hasOwnProperty.call(section, "Pass")) {
			return true;
		}
		if (!Object.prototype.hasOwnProperty.call(section, "Fail")) {
			return true;
		}
		if (!Object.prototype.hasOwnProperty.call(section, "Audit")) {
			return true;
		}
		return false;
	}
}

export default class Section {
	private uuid: string;
	private id: string;
	private title: string;
	private instructor: string;
	private dept: string;
	private year: number;
	private avg: number;
	private pass: number;
	private fail: number;
	private audit: number;

	constructor(data: any) {
		this.uuid = data.id;
		this.id = data.Course;
		this.title = data.Title;
		this.instructor = data.Professor;
		this.dept = data.Subject;
		this.year = data.Year;
		this.avg = data.Avg;
		this.pass = data.Pass;
		this.fail = data.Fail;
		this.audit = data.Audit;
	}

	public getPrefixedFields(id: string): Record<string, any> {
		const prefix = id + "_";
		return {
			[prefix + "uuid"]: this.uuid,
			[prefix + "id"]: this.id,
			[prefix + "title"]: this.title,
			[prefix + "instructor"]: this.instructor,
			[prefix + "dept"]: this.dept,
			[prefix + "year"]: this.year,
			[prefix + "avg"]: this.avg,
			[prefix + "pass"]: this.pass,
			[prefix + "fail"]: this.fail,
			[prefix + "audit"]: this.audit,
		};
	}
}

import { InsightDataset, InsightDatasetKind } from "../controller/IInsightFacade";
import Section from "./Section";

export default class SectionsDataset implements InsightDataset {
	public id: string;
	public kind: InsightDatasetKind;
	public numRows: number;
	public sections: Section[];

	constructor(id: string, kind: InsightDatasetKind, numRows: number, sections: Section[]) {
		this.id = id;
		this.kind = kind;
		this.numRows = numRows;
		this.sections = sections;
	}
}

export default class QueryValidator {
	public datasetID: string;

	constructor(id: string) {
		this.datasetID = id;
	}

	public isValidQuery(query: unknown): boolean {
		// Check if query is of type Object, Reject with InsightError If not
		if (typeof query !== "object" || query === null) {
			return false;
		}

		const parsedQuery = JSON.parse(JSON.stringify(query));
		const topLevelKeys = Object.keys(parsedQuery);

		// Check if only WHERE and OPTIONS exists in topLevelKeys
		const maxTopLevelKeys = 2;
		if (
			!topLevelKeys.includes("WHERE") ||
			!topLevelKeys.includes("OPTIONS") ||
			topLevelKeys.length !== maxTopLevelKeys
		) {
			return false;
		}

		// Check if all keys and fields are valid inside WHERE
		if (!this.isValidWHERE(parsedQuery.WHERE) || !this.isValidOPTIONS(parsedQuery.OPTIONS)) {
			return false;
		}

		// TODO: Check if all keys reference only one dataset

		return true;
	}

	private isValidWHERE(where: any): boolean {
		const whereKeys = Object.keys(where);
		// Check if WHERE is empty
		if (whereKeys.length === 0) {
			return true;
		}

		// Check if WHERE has only 1 FILTER
		if (whereKeys.length !== 1) {
			return false;
		}

		// Check if FILTER is a LogicComparison
		if (whereKeys.includes("AND") || whereKeys.includes("OR")) {
			return this.isValidLogicComparison(where);
		}

		// Check if FILTER is a MComparison
		if (whereKeys.includes("GT") || whereKeys.includes("LT") || whereKeys.includes("EQ")) {
			return this.isValidMComparison(where);
		}

		// Check if FILTER is a SComparision
		if (whereKeys.includes("IS")) {
			return this.isValidSComparison(where);
		}

		// Check if FILTER is a Negation
		if (whereKeys.includes("NOT")) {
			return this.isValidNegation(where);
		}

		// if whereKey doesn't match with the four options, return false
		return false;
	}

	private isValidLogicComparison(filter: any): boolean {
		const logic = Object.keys(filter)[0];
		const filterList = filter[logic];
		for (const logicfilter of filterList) {
			if (!this.isValidWHERE(logicfilter)) {
				return false;
			}
		}
		return true;
	}

	private isValidMComparison(filter: any): boolean {
		const mcomparator = Object.keys(filter)[0];
		const mcomparison = filter[mcomparator];
		const mkey = Object.keys(mcomparison);
		const mkeyText = mkey[0];
		const mfieldValue = mcomparison[mkeyText];

		if (mkey.length !== 1 || this.getValidMkey(mkeyText) === "") {
			return false;
		}

		if (typeof mfieldValue !== "number") {
			return false;
		}
		return true;
	}

	private isValidSComparison(filter: any): boolean {
		const scomparator = Object.keys(filter)[0];
		const scomparison = filter[scomparator];
		const skey = Object.keys(scomparison);
		const skeyText = skey[0];
		const sfieldValue = scomparison[skeyText];

		if (skey.length !== 1 || this.getValidSkey(skeyText) === "") {
			return false;
		}

		if (typeof sfieldValue !== "string" || !this.isValidWildCard(sfieldValue)) {
			return false;
		}

		return true;
	}

	private isValidNegation(filter: any): boolean {
		const notFilter = filter.NOT;

		return this.isValidWHERE(notFilter);
	}

	private isValidOPTIONS(options: any): boolean {
		const optionsKeys = Object.keys(options);

		// there must be either 1 or 2 keys
		const maxOptionsKeys = 2;
		if (optionsKeys.length !== 1 && optionsKeys.length !== maxOptionsKeys) {
			return false;
		}

		// Check if OPTIONS contains COLUMNS and if its the first element
		if (!optionsKeys.includes("COLUMNS") || optionsKeys[0] !== "COLUMNS") {
			return false;
		}

		// If there are two elements, make sure the second element is ORDER
		if (optionsKeys.length === maxOptionsKeys && optionsKeys[1] !== "ORDER") {
			return false;
		}
		// check the validity of each column in columns
		const columns = options[optionsKeys[0]];
		for (const col of columns) {
			if (this.getValidMkey(col) === "" && this.getValidSkey(col) === "") {
				return false;
			}
		}

		// if ORDER exists, check the validity of each key
		if (optionsKeys.length === maxOptionsKeys) {
			const orderKeys = options[optionsKeys[1]];
			if (this.getValidMkey(orderKeys) === "" && this.getValidSkey(orderKeys) === "") {
				return false;
			}
			if (!columns.includes(orderKeys)) {
				return false;
			}
		}

		return true;
	}

	// Validity Functions

	private isValidWildCard(wildcard: string): boolean {
		for (let i = 1; i < wildcard.length - 1; i++) {
			const char: string = wildcard[i];
			if (char === "*") {
				return false;
			}
		}
		return true;
	}

	private getValidMkey(Mkey: string): string {
		if (!this.isValidIDKey(Mkey)) {
			return "";
		}
		const mkey = Mkey.split("_")[1];
		if (mkey === "avg" || mkey === "pass" || mkey === "fail" || mkey === "audit" || mkey === "year") {
			return mkey;
		}
		return "";
	}

	private getValidSkey(Skey: string): string {
		if (!this.isValidIDKey(Skey)) {
			return "";
		}
		const skey = Skey.split("_")[1];
		if (skey === "dept" || skey === "id" || skey === "instructor" || skey === "title" || skey === "uuid") {
			return skey;
		}
		return "";
	}

	private isValidIDKey(key: any): boolean {
		const prefix = key.split("_")[0];

		if (this.datasetID === "") {
			this.datasetID = prefix;
		} else {
			if (prefix !== this.datasetID) {
				return false;
			}
		}

		return true;
	}
}

import { InsightDataset, InsightError, InsightResult, ResultTooLargeError } from "./IInsightFacade";
import Section from "../model/Section";

export default class QueryEngine {
	public datasetID: string;

	constructor(id: string) {
		this.datasetID = id;
	}

	public processQuery(query: any, id: string, datasetMap: Map<string, InsightDataset>): InsightResult[] {
		// Parse Query
		const parsedQuery = JSON.parse(JSON.stringify(query));

		// Parse Dataset
		const dataset = datasetMap.get(id);
		const parsedDataset = JSON.parse(JSON.stringify(dataset));

		let filteredResult = parsedDataset.sections;

		filteredResult = this.processWHERE(parsedQuery.WHERE, filteredResult);
		filteredResult = this.processOPTION(parsedQuery.OPTIONS, filteredResult);

		// AFTER RESULTS HAS BEEN PROCESSED: If the result is greater than 5000, Reject with ResultTooLarge error
		const maximumResults = 5000;
		if (filteredResult.length > maximumResults) {
			throw new ResultTooLargeError("Result is greater than 5000 entries");
		} else {
			return filteredResult;
		}
	}

	private processWHERE(queryWHERE: any, filteredResult: any): Section[] {
		// If WHERE is empty, return all entries
		if (Object.keys(queryWHERE).length === 0) {
			return filteredResult;
		}

		const filter = Object.keys(queryWHERE)[0];

		// IF WHERE has FILTER, pass on current entries to the filter helper
		if (filter === "AND" || filter === "OR") {
			return this.handleLogic(queryWHERE, filteredResult);
		} else if (filter === "GT" || filter === "LT" || filter === "EQ") {
			// TODO: do i have to consider when handleMComparison throws an Error?
			return this.handleMComparison(queryWHERE, filteredResult);
		} else if (filter === "IS") {
			return this.handleSComparison(queryWHERE, filteredResult);
		} else if (filter === "NOT") {
			return this.handleNegation(queryWHERE, filteredResult);
		}
		throw new InsightError(`filter, ${filter}, is NOT valid`);
	}

	private processOPTION(queryOPTION: any, filteredResult: any): Section[] {
		const columnKeys = queryOPTION.COLUMNS;
		const result: Section[] = [];

		for (const section of filteredResult) {
			const reorderedSection: Section = {} as Section;
			for (const key of columnKeys) {
				reorderedSection[key as keyof Section] = section[key];
			}
			result.push(reorderedSection);
		}
		filteredResult = result;

		if (queryOPTION.ORDER !== null) {
			filteredResult = this.processORDER(queryOPTION.ORDER, filteredResult);
		}

		return filteredResult;
	}

	private processORDER(queryORDER: any, filteredResult: any): Section[] {
		filteredResult.sort(function (a: any, b: any) {
			if (typeof queryORDER === "string") {
				if (a[queryORDER] < b[queryORDER]) {
					return -1;
				} else if (a[queryORDER] > b[queryORDER]) {
					return 1;
				} else {
					return 0;
				}
			} else if (typeof queryORDER === "number") {
				return a[queryORDER] - b[queryORDER];
			}
		});
		return filteredResult;
	}

	private handleLogic(queryLOGIC: any, filteredResult: any): Section[] {
		const logic = Object.keys(queryLOGIC)[0];
		const filterList = queryLOGIC[logic];
		let result: Section[] = [];

		// Case AND
		if (logic === "AND") {
			for (const filter of filterList) {
				filteredResult = this.processWHERE(filter, filteredResult);
			}
			result = filteredResult;
		}

		// Case OR
		else {
			// create a huge list of all sections that match each filter
			let filteredOR: Section[] = [];

			for (const filter of filterList) {
				filteredOR = filteredOR.concat(this.processWHERE(filter, filteredResult));
			}

			result = Array.from(new Set(filteredOR));
		}

		return result;
	}

	private handleMComparison(queryMComparator: any, filteredResult: any): Section[] {
		const mcomparator = Object.keys(queryMComparator)[0];
		const mcomparison = queryMComparator[mcomparator];
		const mkey = Object.keys(mcomparison);
		const mkeyText = mkey[0];
		const mfieldValue = mcomparison[mkeyText];
		const result = [];

		for (const section of filteredResult) {
			const sectionValue = section[mkeyText];

			switch (mcomparator) {
				case "EQ": {
					if (sectionValue === mfieldValue) {
						result.push(section);
					}
					break;
				}
				case "GT": {
					if (sectionValue > mfieldValue) {
						result.push(section);
					}
					break;
				}
				case "LT": {
					if (sectionValue < mfieldValue) {
						result.push(section);
					}
					break;
				}
				default:
				// console.error(`Invalid comparator: ${mcomparator}`);
			}
		}
		return result;
	}

	private handleSComparison(querySComparator: any, filteredResult: any): Section[] {
		const scomparator = Object.keys(querySComparator)[0];
		const scomparison = querySComparator[scomparator];
		const skey = Object.keys(scomparison);
		// const skeyText = skey[0];
		const sfieldValue = scomparison[skey[0]];
		const result = [];

		for (const section of filteredResult) {
			const sectionValue = section[skey[0]];

			// Check if sectionValue contains sfieldValue
			if (sfieldValue[0] === "*" && sfieldValue[sfieldValue.length - 1] === "*") {
				const inputstring = sfieldValue.substring(1, sfieldValue.length - 1);
				if (sectionValue.includes(inputstring)) {
					result.push(section);
				}
				continue;
			}
			// Check if sectionValue starts with sfieldValue
			if (sfieldValue[sfieldValue.length - 1] === "*") {
				const inputstring = sfieldValue.substring(0, sfieldValue.length - 1);
				if (sectionValue.startsWith(inputstring)) {
					result.push(section);
				}
				continue;
			}
			// Check if sectionValue ends with sfieldValue
			if (sfieldValue[0] === "*") {
				const inputstring = sfieldValue.substring(1);
				if (sectionValue.endsWith(inputstring)) {
					result.push(section);
				}
				continue;
			}

			// Check if sectionValue === sfieldValue
			if (sectionValue === sfieldValue) {
				result.push(section);
			}
		}
		return result;
	}

	private handleNegation(queryNegation: any, filteredResult: any): Section[] {
		const result = [];
		const negatedResult = this.processWHERE(queryNegation.NOT, filteredResult);

		for (const section of filteredResult) {
			if (!negatedResult.includes(section)) {
				result.push(section);
			}
		}
		return result;
	}
}
